        'A chilling paranormal account from Cape Town (South Africa). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Table Mountain.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว คอยซาน ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of คอยซาน oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ เทเบิลเมาน์เทน',
        'Never whistle or look back if hearing whispers along twilight pathways in Table Mountain.',
        'https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg","title":"เงาร่างทมิฬแห่งหอระฆังร้าง เทเบิลเมาน์เทน (คอยซาน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D0Wzn0_QpG0","title":"ตำนานผีและเรื่องเล่าสยองขวัญรอบโลก","thumbnail":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-table-mountain-11-101',
        'พญานาคินทร์หรือสัตว์ร้ายแห่งสายน้ำลึก เทเบิลเมาน์เทน (คอยซาน)',
        'The Serpentine Deep Water Leviathan of Table Mountain (คอยซาน)',
        'monster',
        'เคปทาวน์ (แอฟริกาใต้)',
        'Cape Town (South Africa)',
        'เทเบิลเมาน์เทน',
        'Table Mountain',
        -33.9628,
        18.3947,
        'water_spirit',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน เคปทาวน์ (แอฟริกาใต้) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ เทเบิลเมาน์เทน',
        'Eyewitness reports of a formidable cryptid stalking Cape Town (South Africa). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Table Mountain.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว คอยซาน ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native คอยซาน folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ เทเบิลเมาน์เทน',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Table Mountain.',
        'https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg","title":"พญานาคินทร์หรือสัตว์ร้ายแห่งสายน้ำลึก เทเบิลเมาน์เทน (คอยซาน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=xo_fMcSLp7Q","title":"สัตว์ลึกลับแห่งพงไพรและสายน้ำโบราณ","thumbnail":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-table-mountain-11-101',
        'วัตถุโบราณต้องสาปแห่งตระกูลขุนนาง เทเบิลเมาน์เทน (คอยซาน)',
        'The Cursed Heirlooms and Bloodline Hex of Table Mountain (คอยซาน)',
        'curse',
        'เคปทาวน์ (แอฟริกาใต้)',
        'Cape Town (South Africa)',
        'เทเบิลเมาน์เทน',
        'Table Mountain',
        -33.9628,
        18.3947,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง เคปทาวน์ (แอฟริกาใต้) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน เทเบิลเมาน์เทน',
        'A grim cautionary curse chronicle from Cape Town (South Africa). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Table Mountain.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว คอยซาน เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of คอยซาน, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ เทเบิลเมาน์เทน',
        'Never remove stones, relics, or votive offerings from Table Mountain.',
        'https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg","title":"วัตถุโบราณต้องสาปแห่งตระกูลขุนนาง เทเบิลเมาน์เทน (คอยซาน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TWCWQq-YNdI","title":"คำสาปแห่งราชวงศ์และสิ่งเร้นลับทางประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-table-mountain-11-101',
        'นครโบราณที่สาบสูญใต้ผืนป่า เทเบิลเมาน์เทน (คอยซาน)',
        'The Lost Sunken Citadel of Table Mountain (คอยซาน)',
        'legend',
        'เคปทาวน์ (แอฟริกาใต้)',
        'Cape Town (South Africa)',
        'เทเบิลเมาน์เทน',
        'Table Mountain',
        -33.9628,
        18.3947,
        'jungle_curse',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง เคปทาวน์ (แอฟริกาใต้) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว คอยซาน ใน เทเบิลเมาน์เทน',
        'A legendary monumental marvel in Cape Town (South Africa). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral คอยซาน engineers in Table Mountain.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ เคปทาวน์ (แอฟริกาใต้) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Cape Town (South Africa), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ เทเบิลเมาน์เทน',
        'Do not deface, carve, or displace ancient stones in Table Mountain.',
        'https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg","title":"นครโบราณที่สาบสูญใต้ผืนป่า เทเบิลเมาน์เทน (คอยซาน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sB7nFq5K_3M","title":"สารคดี อารยธรรมและตำนานโบราณ","thumbnail":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
