        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-kakadu-11-102',
        'อารามโบราณพิทักษ์ผืนป่า คาคาดู (อะบอริจินดรีมไทม์)',
        'The Sacred Mountain Hermitage of Kakadu (อะบอริจินดรีมไทม์)',
        'sacred',
        'นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย)',
        'Northern Territory (Australia)',
        'คาคาดู',
        'Kakadu',
        -12.8183,
        132.8633,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว อะบอริจินดรีมไทม์ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Northern Territory (Australia), serving as the spiritual heart of ancestral อะบอริจินดรีมไทม์ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Northern Territory (Australia), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน คาคาดู',
        'Remove footwear and maintain silence within the inner terrace of Kakadu.',
        'https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg","title":"อารามโบราณพิทักษ์ผืนป่า คาคาดู (อะบอริจินดรีมไทม์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0kKCcsPQekY","title":"เสน่ห์วัดไทย ปฐมเจดีย์และเทวสถานโบราณ","thumbnail":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg"}]'
      );

