        'นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย)',
        'Northern Territory (Australia)',
        'คาคาดู',
        'Kakadu',
        -12.8183,
        132.8633,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน คาคาดู',
        'A grim cautionary curse chronicle from Northern Territory (Australia). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Kakadu.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว อะบอริจินดรีมไทม์ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of อะบอริจินดรีมไทม์, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ คาคาดู',
        'Never remove stones, relics, or votive offerings from Kakadu.',
        'https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg","title":"อาถรรพ์ทางแยกสัญญามนต์ดำ คาคาดู (อะบอริจินดรีมไทม์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TbB9KfaRq70","title":"อาถรรพ์วัตถุต้องคำสาปและโศกนาฏกรรม","thumbnail":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-kakadu-11-102',
        'แท่นหินดาราศาสตร์และภูมิปัญญาบรรพกาล คาคาดู (อะบอริจินดรีมไทม์)',
        'The Archaeoastronomical Stone Ring of Kakadu (อะบอริจินดรีมไทม์)',
        'legend',
        'นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย)',
        'Northern Territory (Australia)',
        'คาคาดู',
        'Kakadu',
        -12.8183,
        132.8633,
        'temple_bell',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว อะบอริจินดรีมไทม์ ใน คาคาดู',
        'A legendary monumental marvel in Northern Territory (Australia). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral อะบอริจินดรีมไทม์ engineers in Kakadu.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Northern Territory (Australia), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ คาคาดู',
        'Do not deface, carve, or displace ancient stones in Kakadu.',
        'https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg","title":"แท่นหินดาราศาสตร์และภูมิปัญญาบรรพกาล คาคาดู (อะบอริจินดรีมไทม์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qD-80cmvTts","title":"มรดกตำนานและนครสาบสูญแห่งประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-rotorua-11-103',
        'มณฑปพระพุทธบาทและรอยจารึกธรรม โรโตรัว (เมารี)',
        'The Sacred Footprint and Scripture Shrine of Rotorua (เมารี)',
        'sacred',
        'เกาะเหนือ (นิวซีแลนด์)',
        'North Island (New Zealand)',
        'โรโตรัว',
        'Rotorua',
        -38.1069,
        176.2197,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน เกาะเหนือ (นิวซีแลนด์) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว เมารี เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of North Island (New Zealand), serving as the spiritual heart of ancestral เมารี heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค เกาะเหนือ (นิวซีแลนด์) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in North Island (New Zealand), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน โรโตรัว',
        'Remove footwear and maintain silence within the inner terrace of Rotorua.',
        'https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg","title":"มณฑปพระพุทธบาทและรอยจารึกธรรม โรโตรัว (เมารี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=EE1yv4CRjzY","title":"เปิดประวัติศาสตร์ มหาเจดีย์ศักดิ์สิทธิ์พันปี","thumbnail":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-rotorua-11-103',
        'พรายน้ำคร่ำครวญริมสายน้ำ โรโตรัว (เมารี)',
        'The Weeping Water Banshee of Rotorua (เมารี)',
        'ghost',
        'เกาะเหนือ (นิวซีแลนด์)',
        'North Island (New Zealand)',
        'โรโตรัว',
        'Rotorua',
        -38.1069,
        176.2197,
        'water_spirit',
        'เรื่องเล่าสยองขวัญประจำถิ่น เกาะเหนือ (นิวซีแลนด์) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ โรโตรัว',
        'A chilling paranormal account from North Island (New Zealand). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Rotorua.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว เมารี ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of เมารี oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ โรโตรัว',
        'Never whistle or look back if hearing whispers along twilight pathways in Rotorua.',
        'https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg","title":"พรายน้ำคร่ำครวญริมสายน้ำ โรโตรัว (เมารี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XtIe-oS07gg","title":"เรื่องเล่าวิญญาณและปราสาทหลอนโบราณ","thumbnail":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-rotorua-11-103',
        'มนุษย์วานรยักษ์แห่งป่าดึกดำบรรพ์ โรโตรัว (เมารี)',
        'The Primeval Forest Ape Cryptid of Rotorua (เมารี)',
        'monster',
        'เกาะเหนือ (นิวซีแลนด์)',
        'North Island (New Zealand)',
        'โรโตรัว',
        'Rotorua',
        -38.1069,
        176.2197,
        'jungle_curse',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน เกาะเหนือ (นิวซีแลนด์) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ โรโตรัว',
        'Eyewitness reports of a formidable cryptid stalking North Island (New Zealand). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Rotorua.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว เมารี ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native เมารี folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ โรโตรัว',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Rotorua.',
        'https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg","title":"มนุษย์วานรยักษ์แห่งป่าดึกดำบรรพ์ โรโตรัว (เมารี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0fdreKvuqgs","title":"การค้นพบสิ่งมีชีวิตลี้ลับและอสุรกายโบราณ","thumbnail":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg"}]'
      );

