        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-mae-rim-11-104',
        'กระจกเงาต้องคำสาปและเงาลวงตา แม่ริม (ล้านนา)',
        'The Cursed Scrying Glass of Mae Rim (ล้านนา)',
        'curse',
        'เชียงใหม่ (ไทย)',
        'Chiang Mai (Thailand)',
        'แม่ริม',
        'Mae Rim',
        18.9617,
        98.965,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง เชียงใหม่ (ไทย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน แม่ริม',
        'A grim cautionary curse chronicle from Chiang Mai (Thailand). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Mae Rim.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ล้านนา เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ล้านนา, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ แม่ริม',
        'Never remove stones, relics, or votive offerings from Mae Rim.',
        'https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg","title":"กระจกเงาต้องคำสาปและเงาลวงตา แม่ริม (ล้านนา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TWCWQq-YNdI","title":"คำสาปแห่งราชวงศ์และสิ่งเร้นลับทางประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
