INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-pa-sang-11-106',
        'บ่อน้ำพุศักดิ์สิทธิ์ไร้ก้นแห่งตำนาน ป่าซาง (หริภุญชัย)',
        'The Bottomless Sacred Cenote of Pa Sang (หริภุญชัย)',
        'legend',
        'ลำพูน (ไทย)',
        'Lamphun (Thailand)',
        'ป่าซาง',
        'Pa Sang',
        18.4983,
        98.9389,
        'water_spirit',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง ลำพูน (ไทย) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว หริภุญชัย ใน ป่าซาง',
        'A legendary monumental marvel in Lamphun (Thailand). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral หริภุญชัย engineers in Pa Sang.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ ลำพูน (ไทย) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Lamphun (Thailand), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ ป่าซาง',
        'Do not deface, carve, or displace ancient stones in Pa Sang.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"บ่อน้ำพุศักดิ์สิทธิ์ไร้ก้นแห่งตำนาน ป่าซาง (หริภุญชัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-khong-chiam-11-107',
        'เทวาลัยโบราณแห่งมหาเทวะ โขงเจียม (อีสานริมโขง)',
        'The Ancient Chola Shiva Shrine of Khong Chiam (อีสานริมโขง)',
        'sacred',
        'อุบลราชธานี (ไทย)',
        'Ubon Ratchathani (Thailand)',
        'โขงเจียม',
        'Khong Chiam',
        15.3047,
        105.5433,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน อุบลราชธานี (ไทย) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว อีสานริมโขง เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Ubon Ratchathani (Thailand), serving as the spiritual heart of ancestral อีสานริมโขง heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค อุบลราชธานี (ไทย) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Ubon Ratchathani (Thailand), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน โขงเจียม',
        'Remove footwear and maintain silence within the inner terrace of Khong Chiam.',
        'https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg","title":"เทวาลัยโบราณแห่งมหาเทวะ โขงเจียม (อีสานริมโขง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=EE1yv4CRjzY","title":"เปิดประวัติศาสตร์ มหาเจดีย์ศักดิ์สิทธิ์พันปี","thumbnail":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-khong-chiam-11-107',
        'ดวงไฟวิญญาณลอยล่องกลางหนองน้ำ โขงเจียม (อีสานริมโขง)',
        'The Will-o''-the-Wisp Ghost Light of Khong Chiam (อีสานริมโขง)',
        'ghost',
        'อุบลราชธานี (ไทย)',
        'Ubon Ratchathani (Thailand)',
        'โขงเจียม',
        'Khong Chiam',
        15.3047,
        105.5433,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น อุบลราชธานี (ไทย) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ โขงเจียม',
        'A chilling paranormal account from Ubon Ratchathani (Thailand). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Khong Chiam.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว อีสานริมโขง ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of อีสานริมโขง oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ โขงเจียม',
        'Never whistle or look back if hearing whispers along twilight pathways in Khong Chiam.',
        'https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg","title":"ดวงไฟวิญญาณลอยล่องกลางหนองน้ำ โขงเจียม (อีสานริมโขง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D0Wzn0_QpG0","title":"ตำนานผีและเรื่องเล่าสยองขวัญรอบโลก","thumbnail":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-khong-chiam-11-107',
        'อสูรครึ่งคนครึ่งสัตว์น้ำแห่งถ้ำมืด โขงเจียม (อีสานริมโขง)',
        'The Amphibious Troglodyte of Khong Chiam (อีสานริมโขง)',
        'monster',
        'อุบลราชธานี (ไทย)',
        'Ubon Ratchathani (Thailand)',
        'โขงเจียม',
        'Khong Chiam',
        15.3047,
        105.5433,
        'water_spirit',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน อุบลราชธานี (ไทย) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ โขงเจียม',
        'Eyewitness reports of a formidable cryptid stalking Ubon Ratchathani (Thailand). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Khong Chiam.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว อีสานริมโขง ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native อีสานริมโขง folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ โขงเจียม',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Khong Chiam.',
        'https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg","title":"อสูรครึ่งคนครึ่งสัตว์น้ำแห่งถ้ำมืด โขงเจียม (อีสานริมโขง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=xo_fMcSLp7Q","title":"สัตว์ลึกลับแห่งพงไพรและสายน้ำโบราณ","thumbnail":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-khong-chiam-11-107',
        'อาถรรพ์บทเพลงและเสียงดนตรีต้องห้าม โขงเจียม (อีสานริมโขง)',
        'The Fatal Melody Hex of Khong Chiam (อีสานริมโขง)',
        'curse',
        'อุบลราชธานี (ไทย)',
        'Ubon Ratchathani (Thailand)',
        'โขงเจียม',
        'Khong Chiam',
        15.3047,
        105.5433,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง อุบลราชธานี (ไทย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน โขงเจียม',
        'A grim cautionary curse chronicle from Ubon Ratchathani (Thailand). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Khong Chiam.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว อีสานริมโขง เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of อีสานริมโขง, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ โขงเจียม',
        'Never remove stones, relics, or votive offerings from Khong Chiam.',
        'https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg","title":"อาถรรพ์บทเพลงและเสียงดนตรีต้องห้าม โขงเจียม (อีสานริมโขง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TWCWQq-YNdI","title":"คำสาปแห่งราชวงศ์และสิ่งเร้นลับทางประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg"}]'
      );

