        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-ueno-12-112',
        'อาถรรพ์ทางแยกสัญญามนต์ดำ อุเอโนะ (เอโดะ)',
        'The Forbidden Crossroads Covenant of Ueno (เอโดะ)',
        'curse',
        'โตเกียว (ญี่ปุ่น)',
        'Tokyo (Japan)',
        'อุเอโนะ',
        'Ueno',
        35.6692,
        139.7281,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง โตเกียว (ญี่ปุ่น) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน อุเอโนะ',
        'A grim cautionary curse chronicle from Tokyo (Japan). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Ueno.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว เอโดะ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of เอโดะ, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ อุเอโนะ',
        'Never remove stones, relics, or votive offerings from Ueno.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"อาถรรพ์ทางแยกสัญญามนต์ดำ อุเอโนะ (เอโดะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

