        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-jongno-12-114',
        'วิหารแก้วศรัทธาและพระพุทธปฏิมาโบราณ จงโน (โชซอน)',
        'The Crystal Vihara and Consecrated Icon of Jongno (โชซอน)',
        'sacred',
        'โซล (เกาหลีใต้)',
        'Seoul (South Korea)',
        'จงโน',
        'Jongno',
        37.5578,
        127.0244,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน โซล (เกาหลีใต้) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว โชซอน เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Seoul (South Korea), serving as the spiritual heart of ancestral โชซอน heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค โซล (เกาหลีใต้) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Seoul (South Korea), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน จงโน',
        'Remove footwear and maintain silence within the inner terrace of Jongno.',
        'https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg","title":"วิหารแก้วศรัทธาและพระพุทธปฏิมาโบราณ จงโน (โชซอน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0kKCcsPQekY","title":"เสน่ห์วัดไทย ปฐมเจดีย์และเทวสถานโบราณ","thumbnail":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg"}]'
      );

