      ) VALUES (
        'pin-curse-chengdu-12-116',
        'คำสาปโลงศพและมัมมี่ผู้ล่วงละเมิด เฉิงตู (สู่ฮั่นโบราณ)',
        'The Desecrated Tomb Hex of Chengdu (สู่ฮั่นโบราณ)',
        'curse',
        'เสฉวน (จีน)',
        'Sichuan (China)',
        'เฉิงตู',
        'Chengdu',
        30.6736,
        104.0947,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง เสฉวน (จีน) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน เฉิงตู',
        'A grim cautionary curse chronicle from Sichuan (China). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Chengdu.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว สู่ฮั่นโบราณ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of สู่ฮั่นโบราณ, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ เฉิงตู',
        'Never remove stones, relics, or votive offerings from Chengdu.',
        'https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg","title":"คำสาปโลงศพและมัมมี่ผู้ล่วงละเมิด เฉิงตู (สู่ฮั่นโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TWCWQq-YNdI","title":"คำสาปแห่งราชวงศ์และสิ่งเร้นลับทางประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg"}]'
      );

