        110.4489,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น หูหนาน (จีน) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ จางเจียเจี้ย',
        'A chilling paranormal account from Hunan (China). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Zhangjiajie.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว ฉู่โบราณ ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of ฉู่โบราณ oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ จางเจียเจี้ย',
        'Never whistle or look back if hearing whispers along twilight pathways in Zhangjiajie.',
        'https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg","title":"ดวงไฟวิญญาณลอยล่องกลางหนองน้ำ จางเจียเจี้ย (ฉู่โบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LbCWDUZhSFc","title":"ปริศนาดวงวิญญาณและคฤหาสน์ต้องห้าม","thumbnail":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-zhangjiajie-12-117',
        'อสูรครึ่งคนครึ่งสัตว์น้ำแห่งถ้ำมืด จางเจียเจี้ย (ฉู่โบราณ)',
        'The Amphibious Troglodyte of Zhangjiajie (ฉู่โบราณ)',
        'monster',
        'หูหนาน (จีน)',
        'Hunan (China)',
        'จางเจียเจี้ย',
        'Zhangjiajie',
        29.1472,
        110.4489,
        'water_spirit',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน หูหนาน (จีน) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ จางเจียเจี้ย',
        'Eyewitness reports of a formidable cryptid stalking Hunan (China). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Zhangjiajie.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว ฉู่โบราณ ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native ฉู่โบราณ folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ จางเจียเจี้ย',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Zhangjiajie.',
        'https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg","title":"อสูรครึ่งคนครึ่งสัตว์น้ำแห่งถ้ำมืด จางเจียเจี้ย (ฉู่โบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8W-DjTLd0mo","title":"สารคดี สัตว์ประหลาดในตำนานและสิ่งลี้ลับ","thumbnail":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-zhangjiajie-12-117',
        'อาถรรพ์บทเพลงและเสียงดนตรีต้องห้าม จางเจียเจี้ย (ฉู่โบราณ)',
        'The Fatal Melody Hex of Zhangjiajie (ฉู่โบราณ)',
        'curse',
        'หูหนาน (จีน)',
        'Hunan (China)',
        'จางเจียเจี้ย',
        'Zhangjiajie',
        29.1472,
        110.4489,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง หูหนาน (จีน) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน จางเจียเจี้ย',
        'A grim cautionary curse chronicle from Hunan (China). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Zhangjiajie.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ฉู่โบราณ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ฉู่โบราณ, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ จางเจียเจี้ย',
        'Never remove stones, relics, or votive offerings from Zhangjiajie.',
        'https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg","title":"อาถรรพ์บทเพลงและเสียงดนตรีต้องห้าม จางเจียเจี้ย (ฉู่โบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TbB9KfaRq70","title":"อาถรรพ์วัตถุต้องคำสาปและโศกนาฏกรรม","thumbnail":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-zhangjiajie-12-117',
        'ยอดผาโทรลล์และรอยเท้าบรรพชนยักษ์ จางเจียเจี้ย (ฉู่โบราณ)',
        'The Petrified Giant Cliffs of Zhangjiajie (ฉู่โบราณ)',
        'legend',
        'หูหนาน (จีน)',
        'Hunan (China)',
        'จางเจียเจี้ย',
        'Zhangjiajie',
        29.1472,
        110.4489,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง หูหนาน (จีน) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว ฉู่โบราณ ใน จางเจียเจี้ย',
        'A legendary monumental marvel in Hunan (China). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral ฉู่โบราณ engineers in Zhangjiajie.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ หูหนาน (จีน) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Hunan (China), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ จางเจียเจี้ย',
        'Do not deface, carve, or displace ancient stones in Zhangjiajie.',
        'https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg","title":"ยอดผาโทรลล์และรอยเท้าบรรพชนยักษ์ จางเจียเจี้ย (ฉู่โบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qD-80cmvTts","title":"มรดกตำนานและนครสาบสูญแห่งประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
